const crypto = require('crypto');

const ONE_MIB = 1024 * 1024;
const DEFAULT_CHARSET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

/**
 * Generates a string containing exactly 1 MiB (1,048,576) random ASCII characters.
 *
 * ASCII characters are used so the string is also 1 MiB when UTF-8 encoded.
 * Uses cryptographically secure randomness and rejection sampling to avoid modulo bias.
 *
 * @param {string} charset Characters to sample from.
 * @returns {string} A 1 MiB random string.
 */
function generateRandom1MBString(charset = DEFAULT_CHARSET) {
  if (typeof charset !== 'string' || charset.length === 0 || charset.length > 256) {
    throw new RangeError('charset must be a non-empty string with at most 256 characters');
  }

  const maxValidByte = Math.floor(256 / charset.length) * charset.length - 1;
  const chars = new Array(ONE_MIB);
  let written = 0;

  while (written < ONE_MIB) {
    const bytes = crypto.randomBytes(Math.min((ONE_MIB - written) * 2, 65536));

    for (const byte of bytes) {
      if (byte > maxValidByte) continue;
      chars[written++] = charset[byte % charset.length];
      if (written === ONE_MIB) break;
    }
  }

  return chars.join('');
}

module.exports = { generateRandom1MBString };

