const fs = require('fs');
const path = require('path');
const { generateRandom1MBString } = require('./randomString1MB');

const LOG_DIR = path.join(__dirname, 'temp-logs');
const DEFAULT_COUNT = 10;

function timestampForFilename(date = new Date()) {
  return date.toISOString().replace(/[:.]/g, '-');
}

function writeRandomLog(index) {
  fs.mkdirSync(LOG_DIR, { recursive: true });

  const filename = `random-${timestampForFilename()}-${String(index).padStart(6, '0')}.log`;
  const filepath = path.join(LOG_DIR, filename);
  const contents = generateRandom1MBString();

  fs.writeFileSync(filepath, contents, 'utf8');
  return filepath;
}

function generateTempLogs(count = DEFAULT_COUNT) {
  if (!Number.isInteger(count) || count < 1) {
    throw new RangeError('count must be a positive integer');
  }

  const written = [];

  for (let i = 1; i <= count; i += 1) {
    const filepath = writeRandomLog(i);
    written.push(filepath);
    console.log(`Wrote ${filepath}`);
  }

  return written;
}

if (require.main === module) {
  const count = process.argv[2] ? Number(process.argv[2]) : DEFAULT_COUNT;
  generateTempLogs(count);
}

module.exports = { generateTempLogs, writeRandomLog };
